select  from meeting
left join sys_dict on meeting.status = sys_dict.id
where meeting.id = #{id}

mapper.update:
update meeting
meeting_type= #{meetingType}, start_week = #{startWeek}, end_week = #{endWeek}, start_date = #{startDate}, end_date = #{endDate}, start_start_time = #{startStartTime},
end_end_time = #{endEndTime}, status = #{status}, meeting_name = #{meetingName}, host = #{host}, participants = #{participants}, location = #{location}, isdelete = #{isdelete}, isshow = #{isshow}
where id = #{id}

mapper.select:
SELECT id FROM meeting
WHERE isdelete = '0' -- 只处理未删除的会议
AND (

(meeting_type = '0' AND (
-- 情况1：会议日期在今天之前，无论几点都已结束
start_date < #{today}
-- 情况2：会议日期就是今天，需判断当前时间是否超过结束时间
OR (start_date = #{today} AND
REPLACE(REPLACE(end_end_time, '上午', ''), '下午', '') <= #{currentTime}
)
))

OR


(meeting_type = '1' AND (
-- 情况1：会议结束日期在今天之前，无论几点都已结束
end_date < #{today}
-- 情况2：会议结束日期就是今天，需判断当前时间是否超过结束时间
OR (end_date = #{today} AND
REPLACE(REPLACE(end_end_time, '上午', ''), '下午', '') <= #{currentTime}
)
))
)
AND tid = #{tid}
AND status NOT IN (#{cancelledStatusId}, #{finishedStatusId})

